-- =====================================================================
-- Datos migrados al esquema normalizado (ISFT 182 "Clementina")
--
-- Uso en Hostinger (una sola base de datos, sin acceso a la base vieja):
--   1. Importar primero docs/esquema_normalizado.sql.
--      Si el hosting no permite CREATE DATABASE, quitar ese bloque y el USE,
--      o importar con la base destino ya seleccionada en phpMyAdmin.
--   2. Importar este archivo con LA MISMA base seleccionada:
--        mysql -u USUARIO -p NOMBRE_BD < insert_datos_migrados.sql
--      (o desde phpMyAdmin, con la base destino seleccionada).
--
-- Reemplaza a docs/migracion_datos.sql + docs/migrar_passwords.php: no
-- necesita importar bd_clementina.sql ni ejecutar PHP en el hosting.
-- Las contraseñas ya vienen hasheadas (password_hash de PHP).
-- Los TRUNCATE de abajo borran los datos de prueba del esquema.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- ---------------------------------------------------------------------
-- Limpiar destino (datos de prueba del esquema_normalizado.sql)
-- ---------------------------------------------------------------------
TRUNCATE TABLE docente_asignaciones;
TRUNCATE TABLE aspirantes_parametros;
TRUNCATE TABLE parametros_matriculacion;
TRUNCATE TABLE parametros_inscripcion;
TRUNCATE TABLE parametros_mesas;
TRUNCATE TABLE parametros_generales;
TRUNCATE TABLE historial_academico;
TRUNCATE TABLE matriculacion_detalle;
TRUNCATE TABLE matriculacion;
TRUNCATE TABLE inscripciones;
TRUNCATE TABLE carrera_sede_turno;
TRUNCATE TABLE correlatividades;
TRUNCATE TABLE carrera_materias;
TRUNCATE TABLE materias;
TRUNCATE TABLE carreras;
TRUNCATE TABLE aspirantes;
TRUNCATE TABLE personal;
TRUNCATE TABLE domicilios_alumno;
TRUNCATE TABLE alumnos;
TRUNCATE TABLE sedes;
TRUNCATE TABLE turnos;
TRUNCATE TABLE codigos_area_telefonicos;
TRUNCATE TABLE codigos_postales;
TRUNCATE TABLE localidades;
TRUNCATE TABLE partidos;
TRUNCATE TABLE provincias;
TRUNCATE TABLE paises;
TRUNCATE TABLE tipos_personal;
TRUNCATE TABLE tipos_documento;

-- ---------------------------------------------------------------------
-- Datos migrados (mysqldump --no-create-info, sin CREATE DATABASE ni USE)
-- ---------------------------------------------------------------------

/*!40101 SET @OLD_CHARACTER_SET_CLIENT=@@CHARACTER_SET_CLIENT */;
/*!40101 SET @OLD_CHARACTER_SET_RESULTS=@@CHARACTER_SET_RESULTS */;
